namespace Challenge;public enum PaymentStatus{Success,Transient,Permanent,CircuitOpen}public interface IPaymentProvider{Task<PaymentStatus> SendAsync(string key,CancellationToken ct);}public sealed class PaymentClient(IPaymentProvider provider){public async Task<PaymentStatus> PayAsync(string key,CancellationToken ct=default){PaymentStatus s=PaymentStatus.Transient;for(int i=0;i<3&&s!=PaymentStatus.Success;i++)s=await provider.SendAsync(Guid.NewGuid().ToString(),ct);return s;}}
